// Página do narrador: escreve o texto, escolhe a voz e ouve/baixa o MP3.
// ── Moldura das páginas (mesmo visual em todos os fluxos grátis) ──
function pagina(titulo, corpo, script) {
  const css = `
:root{--fundo:#f6f5f2;--cartao:#fff;--texto:#1d1d1b;--suave:#6b6b66;--linha:#e3e1db;--acento:#0f766e;--acento2:#115e59;--erro:#b42318;--ok:#067647}
@media (prefers-color-scheme:dark){:root{--fundo:#121412;--cartao:#1b1e1c;--texto:#ecebe7;--suave:#a3a39d;--linha:#2c302d;--acento:#2dd4bf;--acento2:#5eead4;--erro:#f97066;--ok:#47cd89}}
*{box-sizing:border-box}body{margin:0;background:var(--fundo);color:var(--texto);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:20px 16px 48px}h1{font-size:1.45rem;margin:.2em 0 .1em}h2{font-size:1.1rem;margin:1.2em 0 .5em}
.sub{color:var(--suave);margin:0 0 18px}.cartao{background:var(--cartao);border:1px solid var(--linha);border-radius:14px;padding:16px;margin:12px 0}
label{display:block;font-weight:600;margin:12px 0 6px}textarea,input,select{width:100%;padding:11px 12px;border:1px solid var(--linha);border-radius:10px;background:var(--fundo);color:var(--texto);font:inherit}
textarea{min-height:120px;resize:vertical}.linha{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
button,.botao{display:inline-block;background:var(--acento);color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 1rem system-ui,sans-serif;cursor:pointer;text-decoration:none;margin-top:14px}
@media (prefers-color-scheme:dark){button,.botao{color:#04211e}}
button[disabled]{opacity:.55;cursor:wait}.botao.sec{background:transparent;color:var(--acento);border:1px solid var(--acento)}
.aviso{color:var(--suave);font-size:.9rem}.erro{color:var(--erro);font-weight:600}.ok{color:var(--ok);font-weight:600}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.grade img,.grade video{width:100%;border-radius:10px;border:1px solid var(--linha);background:#000}
video,audio{width:100%;margin-top:10px;border-radius:10px}pre{white-space:pre-wrap;background:var(--fundo);border:1px solid var(--linha);border-radius:10px;padding:12px;font-size:.9rem}
.barra{height:8px;background:var(--linha);border-radius:99px;overflow:hidden;margin:10px 0}.barra i{display:block;height:100%;background:var(--acento);width:0;transition:width .6s}
.selo{display:inline-block;font-size:.78rem;border:1px solid var(--linha);border-radius:99px;padding:2px 9px;color:var(--suave);margin:2px 4px 2px 0}
footer{color:var(--suave);font-size:.82rem;margin-top:28px}`;
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + titulo + '</title><style>' + css + '</style></head><body><main>' + corpo +
    '<footer>Feito com serviços grátis e sem chave (Hugging Face, Pollinations, Bing/Google Tradutor). Pode demorar ou falhar quando eles estão cheios.</footer>' +
    '</main>' + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const corpo = `
<h1>🎙️ Narrador grátis</h1>
<p class="sub">Voz neural da Microsoft (a do Bing Tradutor), sem chave e sem pagar. Se ela falhar, sai a voz do Google.</p>
<div class="cartao">
  <label for="texto">Texto para narrar</label>
  <textarea id="texto" maxlength="5000" placeholder="Cole aqui o roteiro do vídeo...">Você sabia que o Sol entrega à Terra, em uma hora, mais energia do que o mundo inteiro usa em um ano?</textarea>
  <div class="linha">
    <div><label for="voz">Voz</label><select id="voz">
      <option value="thalita">Thalita (feminina)</option>
      <option value="andrew">Andrew (masculina)</option>
      <option value="brian">Brian (masculina)</option>
      <option value="emma">Emma (feminina)</option>
      <option value="google">Google Tradutor (reserva)</option></select></div>
    <div><label for="vel">Velocidade</label><select id="vel">
      <option value="-10">Mais devagar</option><option value="0" selected>Normal</option>
      <option value="10">Um pouco rápida</option><option value="20">Rápida (Shorts)</option></select></div>
  </div>
  <button id="ir">Gerar narração</button>
  <p id="estado" class="aviso"></p>
  <audio id="som" controls hidden></audio>
  <a id="baixar" class="botao sec" hidden download="narracao.mp3">Baixar MP3</a>
</div>
<div class="cartao aviso">Usa em outros fluxos: <code>POST</code> neste mesmo endereço com <code>{"texto":"...","voz":"thalita","velocidade":0}</code> → devolve o MP3 (cabeçalhos <code>X-Motor</code> e <code>X-Segundos</code>).</div>`;
const script = `
const $ = id => document.getElementById(id);
$('ir').onclick = async () => {
  const texto = $('texto').value.trim();
  if (!texto) { $('estado').textContent = 'Escreva um texto.'; return; }
  $('ir').disabled = true; $('estado').className = 'aviso'; $('estado').textContent = 'Gerando a voz...';
  try {
    const r = await fetch(location.pathname, { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ texto, voz: $('voz').value, velocidade: Number($('vel').value) }) });
    if (!r.ok || !(r.headers.get('content-type') || '').includes('audio')) {
      const j = await r.json().catch(() => ({}));
      throw new Error(j.erro || ('erro ' + r.status));
    }
    const url = URL.createObjectURL(await r.blob());
    $('som').src = url; $('som').hidden = false; $('som').play().catch(() => {});
    $('baixar').href = url; $('baixar').hidden = false;
    const aviso = decodeURIComponent(r.headers.get('X-Aviso') || '');
    $('estado').className = aviso ? 'aviso' : 'ok';
    $('estado').textContent = 'Pronto: ' + (r.headers.get('X-Segundos') || '?') + ' s, voz ' + (r.headers.get('X-Motor') || '') + (aviso ? ' — ' + aviso : '');
  } catch (e) {
    $('estado').className = 'erro'; $('estado').textContent = 'Não deu: ' + e.message;
  }
  $('ir').disabled = false;
};`;
return [{ json: { html: pagina('Narrador grátis', corpo, script) } }];

// Narra o texto do pedido (POST {texto, voz, velocidade}) e devolve o MP3.
// ── Vozes grátis e sem chave ──
// 1º Bing Tradutor (voz NEURAL da Microsoft): pega os códigos da página pública do tradutor e pede o áudio como o
//    próprio site faz. MP3 16 kHz 32 kbps -> segundos = bytes × 8 ÷ 32000.
//    Só as vozes Multilingual aprovadas pela dona (Antonio e Francisca são PROIBIDAS em todos os projetos).
// 2º Google Tradutor (reserva, voz mais robótica): MP3 24 kHz 64 kbps -> segundos = bytes × 8 ÷ 64000.
const UA_VOZ = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36 Edg/141.0';
const VOZES_BING = {
  thalita: ['pt-BR-ThalitaMultilingualNeural', 'Female'], andrew: ['en-US-AndrewMultilingualNeural', 'Male'],
  brian: ['en-US-BrianMultilingualNeural', 'Male'], emma: ['en-US-EmmaMultilingualNeural', 'Female'] };

function limpaFala(s) {
  return String(s || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '')
    .replace(/[*_#`~|<>]/g, ' ').replace(/\s+/g, ' ').trim();
}

function pedacos(texto, max) {
  const out = [];
  let resto = texto;
  while (resto.length > max) {
    let corte = Math.max(resto.lastIndexOf('. ', max), resto.lastIndexOf('! ', max), resto.lastIndexOf('? ', max));
    if (corte < max * 0.4) corte = Math.max(corte, resto.lastIndexOf(', ', max), resto.lastIndexOf('; ', max));
    if (corte < max * 0.3) corte = resto.lastIndexOf(' ', max);
    if (corte < 1) corte = max;
    out.push(resto.slice(0, corte + 1).trim());
    resto = resto.slice(corte + 1).trim();
  }
  if (resto) out.push(resto);
  return out;
}

const escXml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

async function vozBing(helpers, texto, voz, velocidade) {
  const pag = await helpers.httpRequest({ url: 'https://www.bing.com/translator', returnFullResponse: true, timeout: 20000,
    headers: { 'User-Agent': UA_VOZ, 'Accept-Language': 'pt-BR,pt;q=0.9' } });
  const h = String(pag.body || '');
  const ig = /IG:"([^"]+)"/.exec(h);
  const iid = /data-iid="(translator\.\d+)"/.exec(h);
  const ab = /params_AbusePreventionHelper\s*=\s*\[(\d+),"([^"]+)",(\d+)\]/.exec(h);
  if (!ig || !ab) throw new Error('Bing: a página do tradutor não trouxe os códigos');
  const sc = (pag.headers && (pag.headers['set-cookie'] || pag.headers['Set-Cookie'])) || [];
  const cookie = [].concat(sc).map(c => String(c).split(';')[0]).join('; ');
  const [nomeVoz, genero] = VOZES_BING[voz] || VOZES_BING.thalita;
  const taxa = Math.max(-50, Math.min(100, Number(velocidade) || 0));
  const partes = [];
  for (const p of pedacos(texto, 900)) {
    const ssml = "<speak version='1.0' xml:lang='pt-BR'><voice xml:lang='pt-BR' xml:gender='" + genero + "' name='" + nomeVoz +
      "'><prosody rate='" + (taxa >= 0 ? '+' : '') + taxa + "%'>" + escXml(p) + '</prosody></voice></speak>';
    const corpo = 'ssml=' + encodeURIComponent(ssml) + '&token=' + encodeURIComponent(ab[2]) + '&key=' + ab[1];
    const audio = await helpers.httpRequest({ method: 'POST', timeout: 30000, encoding: 'arraybuffer', body: corpo,
      url: 'https://www.bing.com/tfettts?isVertical=1&&IG=' + ig[1] + '&IID=' + (iid ? iid[1] : 'translator.5023') + '.1',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': UA_VOZ, Cookie: cookie,
        Referer: 'https://www.bing.com/translator', Origin: 'https://www.bing.com' } });
    const b = Buffer.from(audio);
    if (b.length < 800) throw new Error('Bing: áudio vazio');
    partes.push(b);
  }
  const mp3 = Buffer.concat(partes);
  return { mp3, motor: 'bing-' + nomeVoz, segundos: Math.round(mp3.length * 8 / 32000 * 100) / 100 };
}

async function vozGoogle(helpers, texto) {
  const partes = [];
  for (const p of pedacos(texto, 180)) {
    let b = null;
    for (let t = 0; t < 3 && !b; t++) {
      try {
        const d = await helpers.httpRequest({ timeout: 20000, encoding: 'arraybuffer', headers: { 'User-Agent': UA_VOZ },
          url: 'https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=pt-BR&q=' + encodeURIComponent(p) });
        b = Buffer.from(d);
      } catch (e) {
        await new Promise(r => setTimeout(r, 1200 * (t + 1)));
      }
    }
    if (!b || b.length < 500) throw new Error('Google: sem áudio');
    partes.push(b);
  }
  const mp3 = Buffer.concat(partes);
  return { mp3, motor: 'google-tradutor', segundos: Math.round(mp3.length * 8 / 64000 * 100) / 100 };
}

// Tenta a voz neural; se falhar, a do Google. Devolve { mp3, motor, segundos, aviso }.
async function narra(helpers, texto, voz, velocidade) {
  const fala = limpaFala(texto);
  if (!fala) throw new Error('texto vazio');
  if (voz !== 'google') {
    try {
      return await vozBing(helpers, fala, voz, velocidade);
    } catch (e) {
      const r = await vozGoogle(helpers, fala);
      r.aviso = 'voz neural indisponível agora (' + String(e.message || e).slice(0, 120) + '); usada a voz do Google';
      return r;
    }
  }
  return await vozGoogle(helpers, fala);
}

const b = $input.first().json.body || {};
const texto = String(b.texto || '').slice(0, 5000);
try {
  const r = await narra(this.helpers, texto, String(b.voz || 'thalita'), Number(b.velocidade) || 0);
  const bin = await this.helpers.prepareBinaryData(r.mp3, 'narracao.mp3', 'audio/mpeg');
  return [{ json: { ok: true, motor: r.motor, segundos: r.segundos, aviso: encodeURIComponent(r.aviso || '') }, binary: { data: bin } }];
} catch (e) {
  return [{ json: { ok: false, erro: 'Não consegui gerar a voz agora: ' + String(e.message || e).slice(0, 200) } }];
}
